import{_ as a,C as o,c as s,o as i,a3 as t,G as n}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Recurring plans","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/configuration/recurring-plans.md","filePath":"master/sales/crm/configuration/recurring-plans.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/configuration/recurring-plans.md"};function h(c,e,u,g,d,p){const r=o("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="recurring-plans" tabindex="-1">Recurring plans <a class="header-anchor" href="#recurring-plans" aria-label="Permalink to &quot;Recurring plans&quot;">​</a></h1><p>A recurring plan names the period that a recurring revenue covers, such as monthly or yearly. You pick a plan on an opportunity that sells a subscription or a service contract. Aureus uses the plan to work out the monthly amount.</p><blockquote><p><strong>In simple words:</strong> A recurring plan says how many months one recurring payment covers.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Recurring Plans</strong> menu shows only when <strong>Recurring Revenue Plans</strong> is on. Go to <code>CRM → Settings → Manage CRM</code>, turn on <strong>Recurring Revenue Plans</strong> and click <strong>Save changes</strong>. See <a href="./settings.html">CRM settings</a>.</p><p>Open <code>CRM → Configuration → Members → Recurring Plans</code>.</p><h2 id="the-recurring-plan-list" tabindex="-1">The recurring plan list <a class="header-anchor" href="#the-recurring-plan-list" aria-label="Permalink to &quot;The recurring plan list&quot;">​</a></h2>',7)),n(r,{src:"/images1/crm/recurring-plans-list.png",alt:"Recurring plans list with Monthly, Yearly, Over 3 years and Over 5 years"}),e[1]||(e[1]=t('<p>The default plans are <strong>Monthly</strong> (1 month), <strong>Yearly</strong> (12), <strong>Over 3 years</strong> (36) and <strong>Over 5 years</strong> (60).</p><h3 id="views-tabs" tabindex="-1">Views (tabs) <a class="header-anchor" href="#views-tabs" aria-label="Permalink to &quot;Views (tabs)&quot;">​</a></h3><ul><li><strong><em>Active:</em></strong> Plans you can pick. The badge shows how many there are.</li><li><strong><em>Archived:</em></strong> Plans you deleted.</li></ul><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Plan:</em></strong> The name of the plan.</li><li><strong><em>Months:</em></strong> How many months it covers.</li><li><strong><em>Opportunities:</em></strong> How many opportunities use the plan.</li></ul><p><strong>Example:</strong> In the dev data, <strong>Monthly</strong> and <strong>Yearly</strong> each have 8 opportunities. The two longer plans have none.</p><h3 id="search-order-and-export" tabindex="-1">Search, order and export <a class="header-anchor" href="#search-order-and-export" aria-label="Permalink to &quot;Search, order and export&quot;">​</a></h3><ul><li>Type in the search box to find a plan.</li><li>Click <strong>Plan</strong> or <strong>Months</strong> to sort.</li><li>Drag a row handle to change the order in which plans are listed on the opportunity form.</li><li>Select rows and use the bulk actions to export, delete, restore or delete for good.</li></ul><h2 id="create-a-recurring-plan" tabindex="-1">Create a recurring plan <a class="header-anchor" href="#create-a-recurring-plan" aria-label="Permalink to &quot;Create a recurring plan&quot;">​</a></h2><ol><li>Go to <code>CRM → Configuration → Members → Recurring Plans</code>.</li><li>Click <strong>New Recurring Plan</strong>.</li><li>Fill in the form.</li><li>Click <strong>Create</strong>.</li></ol>',10)),n(r,{src:"/images1/crm/recurring-plans-form.png",alt:"Create Recurring Plan dialog filled with Every 6 months and 6 months"}),e[2]||(e[2]=t('<ul><li><strong><em>Plan name:</em></strong> The name your team sees. Required. Up to 255 characters. The hint reads <code>e.g. Monthly</code>.</li><li><strong><em>Number of months:</em></strong> How many months the recurring revenue covers. Required. A whole number of at least 1. It starts at 1. Monthly is 1 and Yearly is 12.</li></ul><p><strong>Example:</strong> Name <code>Every 6 months</code> and enter 6 months. A notice says <strong>Recurring plan created</strong>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Where</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Edit</strong></td><td>Active tab</td><td>Changes the name or months. A notice says <strong>Recurring plan updated</strong>.</td></tr><tr><td><strong>Delete</strong></td><td>Active tab</td><td>Moves the plan to <strong>Archived</strong>.</td></tr><tr><td><strong>Restore</strong></td><td>Archived tab</td><td>Brings the plan back. A notice says <strong>Recurring plan restored</strong>.</td></tr><tr><td><strong>Delete</strong> (permanent)</td><td>Archived tab</td><td>Removes the plan for good.</td></tr></tbody></table><h2 id="use-a-plan-on-an-opportunity" tabindex="-1">Use a plan on an opportunity <a class="header-anchor" href="#use-a-plan-on-an-opportunity" aria-label="Permalink to &quot;Use a plan on an opportunity&quot;">​</a></h2><p>On an opportunity, two fields appear when the setting is on.</p><ul><li><strong><em>Recurring Revenue:</em></strong> The amount of one recurring payment. It starts at 0.</li><li><strong><em>Recurring Plan:</em></strong> The plan that the payment covers. It is required as soon as <strong>Recurring Revenue</strong> is above 0.</li></ul><p>Monthly recurring revenue is <strong>Recurring Revenue</strong> divided by the plan months. A revenue of 96,000 on <strong>Over 3 years</strong>, which is 36 months, is about 2,666.67 a month.</p><p>On the forecast, a card shows the recurring revenue and plan, for example <code>+ $18,000.00 Yearly</code>. See <a href="./../reporting/forecast.html">Forecast</a>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>An opportunity keeps a link to its plan, even if you archive the plan later.</li><li>Editing the months of a plan changes the monthly amount on every opportunity that uses it.</li><li>If you turn the setting off, the plans and the saved values stay. Only the menu and fields are hidden.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./settings.html">CRM settings</a></li><li><a href="./../pipeline/manage-opportunities.html">Manage opportunities</a></li><li><a href="./../reporting/forecast.html">Forecast</a></li><li><a href="./">CRM configuration</a></li></ul>',13))])}const f=a(l,[["render",h]]);export{y as __pageData,f as default};
